import React, { useState } from "react";
import { Footer, Navbar } from "../components";
import { useSelector } from "react-redux";
import { ethers } from "ethers";
import { Link } from "react-router-dom";

const Checkout = () => {
  const state = useSelector((state) => state.handleCart);

  // Wallet and transaction state
  const [walletAddress, setWalletAddress] = useState(null);
  const [txStatus, setTxStatus] = useState("");
  const [isPending, setIsPending] = useState(false);

  // Connect MetaMask
  const connectWallet = async () => {
    if (window.ethereum) {
      try {
        const accounts = await window.ethereum.request({
          method: "eth_requestAccounts",
        });
        setWalletAddress(accounts[0]);
        setTxStatus("✅ Wallet connected");
      } catch (err) {
        console.error(err);
        setTxStatus("❌ Wallet connection failed");
      }
    } else {
      alert("MetaMask not found. Please install it.");
    }
  };

  // Disconnect MetaMask
  const disconnectWallet = () => {
    setWalletAddress(null);
    setTxStatus("👋 Wallet disconnected");
  };

  // Simulate a payment transaction
  const simulateTransaction = async () => {
    setTxStatus("⏳ Waiting for confirmation in wallet...");
    setIsPending(true);

    try {
      // Simulate confirmation delay
      await new Promise((resolve) => setTimeout(resolve, 2000));

      setTxStatus("⛏️ Mining transaction...");
      await new Promise((resolve) => setTimeout(resolve, 3000));

      setIsPending(false);
      setTxStatus("🎉 Transaction completed! Minted!");
    } catch (err) {
      setIsPending(false);
      setTxStatus("❌ Transaction failed");
    }
  };

  const EmptyCart = () => {
    return (
      <div className="container py-5">
        <h3 className="text-center">Your Cart is Empty</h3>
        <div className="text-center mt-4">
          <Link to="/" className="btn btn-outline-dark">
            Go Shopping
          </Link>
        </div>
      </div>
    );
  };

  const ShowCheckout = () => {
    const total = state.reduce((acc, item) => acc + item.price * item.qty, 0);

    return (
      <div className="container py-5">
        <h3 className="mb-4">Your Cart</h3>
        <ul className="list-group mb-3">
          {state.map((item) => (
            <li
              className="list-group-item d-flex justify-content-between lh-sm"
              key={item.id}
            >
              <div>
                <h6 className="my-0">{item.title}</h6>
                <small className="text-muted">{item.description}</small>
              </div>
              <span className="text-muted">${item.price * item.qty}</span>
            </li>
          ))}
          <li className="list-group-item d-flex justify-content-between">
            <strong>Total</strong>
            <strong>${total.toFixed(2)}</strong>
          </li>
        </ul>

        {/* Wallet Connection Section */}
        {walletAddress ? (
          <div className="d-grid gap-2 mb-3">
            <button className="btn btn-success" disabled>
              Connected: {walletAddress.slice(0, 6)}...{walletAddress.slice(-4)}
            </button>
            <button className="btn btn-outline-danger" onClick={disconnectWallet}>
              Disconnect Wallet
            </button>
          </div>
        ) : (
          <button
            onClick={connectWallet}
            className="btn btn-outline-primary w-100 mb-3"
          >
            Connect MetaMask
          </button>
        )}

        {/* Simulate Transaction */}
        <button
          onClick={simulateTransaction}
          disabled={!walletAddress || isPending}
          className="btn btn-primary w-100"
        >
          {isPending ? "⛏️ Processing..." : "Pay with MetaMask"}
        </button>

        {/* Status Message */}
        {txStatus && (
          <div className="alert alert-info mt-3 text-center">{txStatus}</div>
        )}
      </div>
    );
  };

  return (
    <>
      <Navbar />
      {state.length === 0 ? <EmptyCart /> : <ShowCheckout />}
      <Footer />
    </>
  );
};

export default Checkout;
